59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. On successful owner create an audit line is emitted here carrying
74	     * the newly assigned owner id, customer code, registration date and membership level.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        normalizeAddress(ownerFieldsDto);
125	        validateRequiredFields(ownerFieldsDto);
126	        normalizeTelephone(ownerFieldsDto);
127	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
128	        rejectDuplicateHousehold(ownerFieldsDto);
129	        rejectCityAtCapacity(ownerFieldsDto.getCity());
130	        defaultRegistrationDate(ownerFieldsDto);
131	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
132	        normalizeEmail(ownerFieldsDto);
133	        HttpHeaders headers = new HttpHeaders();
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        assignCustomerCode(owner);
136	        assignHouseholdId(owner);
137	        assignHouseholdMemberCount(owner);
138	        assignNamesakeCount(owner);
139	        assignMembershipNumber(owner);
140	        assignBulkSignupWarning(owner);
141	        this.clinicService.saveOwner(owner);
142	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
143	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        normalizeEmail(ownerFieldsDto);
158	        currentOwner.setAddress(ownerFieldsDto.getAddress());
159	        currentOwner.setCity(ownerFieldsDto.getCity());
160	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
161	        currentOwner.setLastName(ownerFieldsDto.getLastName());
162	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
163	        currentOwner.setEmail(ownerFieldsDto.getEmail());
164	        this.clinicService.saveOwner(currentOwner);
165	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Transactional
170	    @Override
171	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        this.clinicService.deleteOwner(owner);
177	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Pet pet = petMapper.toPet(petFieldsDto);
189	        owner.setId(ownerId);
190	        pet.setOwner(owner);
191	        pet.getType().setName(null);
192	        this.clinicService.savePet(pet);
193	        PetDto petDto = petMapper.toPetDto(pet);
194	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
195	            .buildAndExpand(pet.getId()).toUri());
196	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
202	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
203	        if (currentOwner != null) {
204	            Pet currentPet = this.clinicService.findPetById(petId);
205	            if (currentPet != null) {
206	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
207	                currentPet.setName(petFieldsDto.getName());
208	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
209	                this.clinicService.savePet(currentPet);
210	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
211	            }
212	        }
213	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
219	        HttpHeaders headers = new HttpHeaders();
220	        Visit visit = visitMapper.toVisit(visitFieldsDto);
221	        Pet pet = new Pet();
222	        pet.setId(petId);
223	        visit.setPet(pet);
224	        this.clinicService.saveVisit(visit);
225	        VisitDto visitDto = visitMapper.toVisitDto(visit);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
227	            .buildAndExpand(visit.getId()).toUri());
228	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
229	    }
230	
231	
232	    /**
233	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
234	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
235	     * Validation already rejects {@code null} values and the pattern-constrained fields
236	     * when blank, but {@code address} and {@code city} have no pattern, so a
237	     * whitespace-only value would otherwise slip through.
238	     *
239	     * @param ownerFieldsDto the submitted owner fields
240	     * @throws RequiredFieldsMissingException if any required field is missing or blank
241	     */
242	    /**
243	     * Common street-type abbreviations expanded during address normalization. Keys are the
244	     * upper-cased abbreviation tokens; values are their canonical expansions.
245	     */
246	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
247	        "ST", "STREET",
248	        "RD", "ROAD",
249	        "AVE", "AVENUE");
250	
251	    /**
252	     * Normalizes the submitted address on create and writes the canonical value back onto the
253	     * request so it is persisted, echoed back, and used for every downstream address comparison
254	     * (household duplicate detection and the household id). The value is trimmed, internal
255	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
256	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
257	     * {@code null} address is left untouched so the required-field check can report it as missing.
258	     *
259	     * @param ownerFieldsDto the submitted owner fields
260	     */
261	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
262	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
263	    }
264	
265	    /**
266	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
267	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
268	     * expanded to its full form. A {@code null} value is returned unchanged.
269	     *
270	     * @param raw the address to canonicalize, possibly {@code null}
271	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
272	     */
273	    private static String normalizeAddress(String raw) {
274	        if (raw == null) {
275	            return null;
276	        }
277	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
278	        if (collapsed.isEmpty()) {
279	            return collapsed;
280	        }
281	        String[] tokens = collapsed.split(" ");
282	        StringBuilder sb = new StringBuilder(collapsed.length());
283	        for (int i = 0; i < tokens.length; i++) {
284	            if (i > 0) {
285	                sb.append(' ');
286	            }
287	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
288	        }
289	        return sb.toString();
290	    }
291	
292	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
293	        List<String> errors = new ArrayList<>();
294	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
295	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
296	        requireText("address", ownerFieldsDto.getAddress(), errors);
297	        requireText("city", ownerFieldsDto.getCity(), errors);
298	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
299	        if (!errors.isEmpty()) {
300	            throw new RequiredFieldsMissingException(errors);
301	        }
302	    }
303	
304	    private static void requireText(String field, String value, List<String> errors) {
305	        if (value == null || value.isBlank()) {
306	            errors.add(field);
307	        }
308	    }
309	
310	    /**
311	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
312	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
313	     * and echoed back in that form.
314	     *
315	     * @param ownerFieldsDto the submitted owner fields
316	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
317	     *                                        valid E.164 number
318	     */
319	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
320	        String e164 = toE164(ownerFieldsDto.getTelephone());
321	        if (e164 == null) {
322	            throw new RequiredFieldsMissingException(List.of("telephone"));
323	        }
324	        ownerFieldsDto.setTelephone(e164);
325	    }
326	
327	    /**
328	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
329	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
330	     * and country code are present they are kept; otherwise country code {@code '+61'} is
331	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
332	     * must contain 8 to 15 digits after the {@code '+'}.
333	     *
334	     * @param raw the submitted telephone, possibly {@code null}
335	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
336	     */
337	    private static String toE164(String raw) {
338	        if (raw == null) {
339	            return null;
340	        }
341	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
342	        String digits;
343	        if (cleaned.startsWith("+")) {
344	            digits = cleaned.substring(1);
345	        } else {
346	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
347	            digits = "61" + national;
348	        }
349	        if (!digits.matches("[0-9]{8,15}")) {
350	            return null;
351	        }
352	        return "+" + digits;
353	    }
354	
355	    /**
356	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
357	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
358	     * each stored owner's telephone is normalized the same way before comparison so differing
359	     * input formats collapse to the same value.
360	     *
361	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
362	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
363	     *                                     same E.164 telephone
364	     */
365	    /**
366	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
367	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
368	     * the parts may contain whitespace or a second {@code @}.
369	     */
370	    private static final Pattern EMAIL_PATTERN =
371	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
372	
373	    /**
374	     * Normalizes the submitted email when present: the value is trimmed, required to be a
375	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
376	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
377	     *
378	     * @param ownerFieldsDto the submitted owner fields
379	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
380	     */
381	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
382	        String email = ownerFieldsDto.getEmail();
383	        if (email == null) {
384	            return;
385	        }
386	        String trimmed = email.strip();
387	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
388	            throw new InvalidEmailException(email);
389	        }
390	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
391	    }
392	
393	    /**
394	     * Establishes the effective registration date on create and rolls it onto a business day.
395	     * When the client does not supply a {@code registrationDate} it defaults to the server's
396	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
397	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
398	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
399	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
400	     * the membership number's year segment and the daily create-limit).
401	     *
402	     * @param ownerFieldsDto the submitted owner fields
403	     */
404	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
405	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
406	        if (effective == null) {
407	            effective = LocalDate.now();
408	        }
409	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
410	    }
411	
412	    /**
413	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
414	     * following Monday; any weekday is returned unchanged.
415	     *
416	     * @param date the date to adjust
417	     * @return the same date when it is a weekday, otherwise the next Monday
418	     */
419	    private static LocalDate toBusinessDay(LocalDate date) {
420	        return switch (date.getDayOfWeek()) {
421	            case SATURDAY -> date.plusDays(2);
422	            case SUNDAY -> date.plusDays(1);
423	            default -> date;
424	        };
425	    }
426	
427	    /**
428	     * Assigns the owner's {@code customerCode} on create, formatted
429	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
430	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
431	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
432	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
433	     *
434	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
435	     */
436	    private void assignCustomerCode(Owner owner) {
437	        String city = owner.getCity();
438	        String lastName = owner.getLastName();
439	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
440	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
441	        long sequence = this.clinicService.findAllOwners().stream()
442	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
443	            .count() + 1;
444	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
445	    }
446	
447	    /**
448	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
449	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
450	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
451	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
452	     * canonicalized fields, every owner in the same household — including one joining an existing
453	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
454	     * order.
455	     *
456	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
457	     */
458	    private void assignHouseholdId(Owner owner) {
459	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
460	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
461	    }
462	
463	    /**
464	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
465	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
466	     * after this create. Because {@code householdId} is derived from the owner's collapsed
467	     * {@code lastName} and {@code address} (see {@link #assignHouseholdId}), the count reflects every
468	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
469	     * The count is taken before this owner is persisted, so it is one more than the number of
470	     * existing household members.
471	     *
472	     * @param owner the owner being created (with its {@code householdId} already assigned)
473	     */
474	    private void assignHouseholdMemberCount(Owner owner) {
475	        String householdId = owner.getHouseholdId();
476	        long existing = this.clinicService.findAllOwners().stream()
477	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
478	            .count();
479	        owner.setHouseholdMemberCount((int) (existing + 1));
480	    }
481	
482	    /**
483	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
484	     * already share this owner's {@code firstName} and {@code lastName}, compared
485	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
486	     * pre-existing namesakes.
487	     *
488	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
489	     */
490	    private void assignNamesakeCount(Owner owner) {
491	        String firstName = owner.getFirstName();
492	        String lastName = owner.getLastName();
493	        long count = this.clinicService.findAllOwners().stream()
494	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
495	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
496	            .count();
497	        owner.setNamesakeCount((int) count);
498	    }
499	
500	    /**
501	     * Assigns the owner's {@code membershipNumber} on create, formatted
502	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
503	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
504	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
505	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
506	     *
507	     * @param owner the owner being created (with its {@code customerCode} and
508	     *              {@code registrationDate} already set)
509	     */
510	    private void assignMembershipNumber(Owner owner) {
511	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
512	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
513	    }
514	
515	    /**
516	     * The number of owners that must already carry a registration date before a subsequent
517	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
518	     * once the count of owners already registered on that day <em>exceeds</em> this value.
519	     */
520	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
521	
522	    /**
523	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
524	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
525	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
526	     * existing owners before this one is persisted, so it reflects only the owners already
527	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
528	     *
529	     * @param owner the owner being created (with its {@code registrationDate} already set)
530	     */
531	    private void assignBulkSignupWarning(Owner owner) {
532	        LocalDate registrationDate = owner.getRegistrationDate();
533	        long count = this.clinicService.findAllOwners().stream()
534	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
535	            .count();
536	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
537	    }
538	
539	    /**
540	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
541	     *
542	     * @param value the string to hash
543	     * @return the 64-character lower-case hex digest
544	     */
545	    private static String sha256Hex(String value) {
546	        try {
547	            byte[] digest = MessageDigest.getInstance("SHA-256")
548	                .digest(value.getBytes(StandardCharsets.UTF_8));
549	            StringBuilder sb = new StringBuilder(digest.length * 2);
550	            for (byte b : digest) {
551	                sb.append(String.format("%02x", b));
552	            }
553	            return sb.toString();
554	        }
555	        catch (NoSuchAlgorithmException e) {
556	            throw new IllegalStateException("SHA-256 not available", e);
557	        }
558	    }
559	
560	    private void rejectDuplicateTelephone(String normalizedTelephone) {
561	        boolean duplicate = this.clinicService.findAllOwners().stream()
562	            .map(Owner::getTelephone)
563	            .map(OwnerRestControllerV1::toE164)
564	            .filter(telephone -> telephone != null)
565	            .anyMatch(normalizedTelephone::equals);
566	        if (duplicate) {
567	            throw new DuplicateTelephoneException(normalizedTelephone);
568	        }
569	    }
570	
571	    /**
572	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
573	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
574	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
575	     * still counts as the same household. The check is skipped when the request opts in via
576	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
577	     * the existing one.
578	     *
579	     * @param ownerFieldsDto the submitted owner fields
580	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
581	     *                                     last name and address and the request did not opt in
582	     */
583	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
584	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
585	            return;
586	        }
587	        String lastName = collapse(ownerFieldsDto.getLastName());
588	        String address = collapse(ownerFieldsDto.getAddress());
589	        boolean duplicate = this.clinicService.findAllOwners().stream()
590	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
591	                && collapse(owner.getAddress()).equals(address));
592	        if (duplicate) {
593	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
594	        }
595	    }
596	
597	    /**
598	     * The maximum number of owners permitted in a single city. A create is rejected once the
599	     * owner's city already contains this many owners.
600	     */
601	    private static final long CITY_CAPACITY = 50;
602	
603	    /**
604	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
605	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
606	     * before this owner is persisted.
607	     *
608	     * @param city the submitted city
609	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
610	     */
611	    private void rejectCityAtCapacity(String city) {
612	        long count = this.clinicService.findAllOwners().stream()
613	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
614	            .count();
615	        if (count >= CITY_CAPACITY) {
616	            throw new CityAtCapacityException(city);
617	        }
618	    }
619	
620	    /**
621	     * The maximum number of owners permitted to be created in a single day. A create is
622	     * rejected once this many owners already carry today's {@code registrationDate}.
623	     */
624	    private static final long DAILY_LIMIT = 100;
625	
626	    /**
627	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
628	     * business day as their {@code registrationDate}. The day counted against is this create's
629	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
630	     * so owners are counted per adjusted business day. The count is taken before this owner is
631	     * persisted.
632	     *
633	     * @param businessDay the effective, business-day-adjusted registration date of this create
634	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
635	     */
636	    private void rejectDailyLimit(LocalDate businessDay) {
637	        long count = this.clinicService.findAllOwners().stream()
638	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
639	            .count();
640	        if (count >= DAILY_LIMIT) {
641	            throw new DailyOwnerLimitExceededException(businessDay);
642	        }
643	    }
644	
645	    /**
646	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
647	     * every internal run of whitespace is collapsed to a single space, and the result is
648	     * lower-cased. A {@code null} value collapses to the empty string.
649	     *
650	     * @param value the value to canonicalize, possibly {@code null}
651	     * @return the collapsed, lower-cased value
652	     */
653	    private static String collapse(String value) {
654	        if (value == null) {
655	            return "";
656	        }
657	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
658	    }
659	
660	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
661	    @Override
662	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
663	        Owner owner = this.clinicService.findOwnerById(ownerId);
664	        if (owner != null) {
665	            Pet pet = owner.getPet(petId);
666	            if (pet != null) {
667	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
668	            }
669	        }
670	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
671	    }
672	}
