16	
17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.CityAtCapacityException;
33	import org.springframework.samples.petclinic.rest.controller.DailyOwnerLimitExceededException;
34	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
35	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
36	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
37	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
38	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
39	import org.springframework.security.access.AccessDeniedException;
40	import org.springframework.validation.BindingResult;
41	import org.springframework.validation.FieldError;
42	import org.springframework.web.bind.MethodArgumentNotValidException;
43	import org.springframework.web.bind.annotation.ControllerAdvice;
44	import org.springframework.web.bind.annotation.ExceptionHandler;
45	import org.springframework.web.bind.annotation.ResponseBody;
46	
47	/**
48	 * Global Exception handler for REST controllers.
49	 * <p>
50	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
51	 *
52	 * @author Vitaliy Fedoriv
53	 * @author Alexander Dudkin
54	 */
55	@ControllerAdvice
56	public class ExceptionControllerAdvice {
57	
58	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
59	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
60	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
61	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
62	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
63	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
64	    private static final String ERROR_INVALID_EMAIL = "The request contains an invalid email address";
65	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
66	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
67	
68	    /**
69	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
70	     * class.
71	     *
72	     * @param e     Object referring to the thrown exception.
73	     * @param status HTTP response status.
74	     * @param url URL request.
75	     */
76	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
77	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
78	        problemDetail.setType(URI.create(url.toString()));
79	        problemDetail.setTitle(e.getClass().getSimpleName());
80	        problemDetail.setDetail(detail);
81	        problemDetail.setProperty("timestamp", Instant.now());
82	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
83	        return problemDetail;
84	    }
85	
86	    /**
87	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
88	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
89	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
90	     * would catch it and report an authorization failure as a 500.
91	     *
92	     * @param e The {@link AccessDeniedException} to propagate
93	     * @throws AccessDeniedException always
94	     */
95	    @ExceptionHandler(AccessDeniedException.class)
96	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
97	        throw e;
98	    }
99	
100	    /**
101	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
102	     *
103	     * @param e The {@link Exception} to be handled
104	     * @param request {@link HttpServletRequest} object referring to the current request.
105	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
106	     */
107	    @ExceptionHandler(Exception.class)
108	    @ResponseBody
109	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
110	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
111	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
112	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
113	        return ResponseEntity.status(status).body(detail);
114	    }
115	
116	    /**
117	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
118	     * method returns a 404 Not Found status if an entity does not exist.
119	     *
120	     * @param e The {@link DataIntegrityViolationException} to be handled
121	     * @param request {@link HttpServletRequest} object referring to the current request.
122	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
123	     */
124	    @ExceptionHandler(DataIntegrityViolationException.class)
125	    @ResponseBody
126	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
127	        logger.warn("Data integrity violation at {} {}: {}",
128	            request.getMethod(),
129	            request.getRequestURI(),
130	            e.getMessage());
131	        logger.debug("Data integrity violation stacktrace", e);
132	        HttpStatus status = HttpStatus.NOT_FOUND;
133	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
134	        return ResponseEntity.status(status).body(detail);
135	    }
136	
137	    /**
138	     * Handles exception thrown by Bean Validation on controller methods parameters
139	     *
140	     * @param e The {@link MethodArgumentNotValidException} to be handled
141	     * @param request {@link HttpServletRequest} object referring to the current request.
142	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
143	     */
144	    @ExceptionHandler(MethodArgumentNotValidException.class)
145	    @ResponseBody
146	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
147	        HttpStatus status = HttpStatus.BAD_REQUEST;
148	        BindingErrorsResponse errors = new BindingErrorsResponse();
149	        BindingResult bindingResult = e.getBindingResult();
150	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
151	        List<String> invalidFields = bindingResult.getFieldErrors().stream()
152	            .map(FieldError::getField)
153	            .distinct()
154	            .toList();
155	        detail.setProperty("errors", invalidFields);
156	        if (bindingResult.hasErrors()) {
157	            errors.addAllErrors(bindingResult);
158	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
159	                .map(fieldError -> {
160	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
161	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
162	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
163	                        fieldError.getField(),
164	                        defaultMessage,
165	                        rejectedValue);
166	                    return new ValidationMessageDto(message)
167	                        .putAdditionalProperty("field", fieldError.getField())
168	                        .putAdditionalProperty("rejectedValue", rejectedValue)
169	                        .putAdditionalProperty("defaultMessage", defaultMessage);
170	                })
171	                .toList();
172	            logger.debug("Validation error at {} {}: {}",
173	                request.getMethod(),
174	                request.getRequestURI(),
175	                bindingResult.getFieldErrors());
176	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
177	            return ResponseEntity.status(status).body(detail);
178	        }
179	        return ResponseEntity.status(status).body(detail);
180	    }
181	
182	    /**
183	     * Handles {@link RequiredFieldsMissingException} raised when a request omits or blanks
184	     * out mandatory fields. Returns a 400 Bad Request whose body carries an {@code errors}
185	     * array listing the name of each offending field.
186	     *
187	     * @param e The {@link RequiredFieldsMissingException} to be handled
188	     * @param request {@link HttpServletRequest} object referring to the current request.
189	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
190	     */
191	    @ExceptionHandler(RequiredFieldsMissingException.class)
192	    @ResponseBody
193	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
194	        HttpStatus status = HttpStatus.BAD_REQUEST;
195	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
196	        detail.setProperty("errors", e.getFields());
197	        logger.debug("Missing required fields at {} {}: {}",
198	            request.getMethod(),
199	            request.getRequestURI(),
200	            e.getFields());
201	        return ResponseEntity.status(status).body(detail);
202	    }
203	
204	    /**
205	     * Handles {@link DuplicateTelephoneException} raised when a create request supplies a
206	     * normalized telephone already used by another owner. Returns a 409 Conflict whose body
207	     * carries an {@code errors} array naming the {@code telephone} field.
208	     *
209	     * @param e The {@link DuplicateTelephoneException} to be handled
210	     * @param request {@link HttpServletRequest} object referring to the current request.
211	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
212	     */
213	    /**
214	     * Handles {@link InvalidEmailException} raised when a create or update request supplies an
215	     * {@code email} that is present but not a syntactically valid address. Returns a 400 Bad
216	     * Request whose body carries an {@code errors} array naming the {@code email} field.
217	     *
218	     * @param e The {@link InvalidEmailException} to be handled
219	     * @param request {@link HttpServletRequest} object referring to the current request.
220	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
221	     */
222	    @ExceptionHandler(InvalidEmailException.class)
223	    @ResponseBody
224	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
225	        HttpStatus status = HttpStatus.BAD_REQUEST;
226	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_EMAIL);
227	        detail.setProperty("errors", List.of("email"));
228	        logger.debug("Invalid email at {} {}: {}",
229	            request.getMethod(),
230	            request.getRequestURI(),
231	            e.getEmail());
232	        return ResponseEntity.status(status).body(detail);
233	    }
234	
235	    @ExceptionHandler(DuplicateTelephoneException.class)
236	    @ResponseBody
237	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
238	        HttpStatus status = HttpStatus.CONFLICT;
239	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
240	        detail.setProperty("errors", List.of("telephone"));
241	        logger.debug("Duplicate telephone at {} {}: {}",
242	            request.getMethod(),
243	            request.getRequestURI(),
244	            e.getTelephone());
245	        return ResponseEntity.status(status).body(detail);
246	    }
247	
248	    /**
249	     * Handles {@link DuplicateHouseholdException} raised when a create request supplies a
250	     * last name and address already used by another owner (compared case-insensitively with
251	     * collapsed whitespace) without opting in via {@code sharesHousehold}. Returns a 409
252	     * Conflict whose body carries an {@code errors} array naming the {@code lastName} and
253	     * {@code address} fields.
254	     *
255	     * @param e The {@link DuplicateHouseholdException} to be handled
256	     * @param request {@link HttpServletRequest} object referring to the current request.
257	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
258	     */
259	    @ExceptionHandler(DuplicateHouseholdException.class)
260	    @ResponseBody
261	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
262	        HttpStatus status = HttpStatus.CONFLICT;
263	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
264	        detail.setProperty("errors", List.of("lastName", "address"));
265	        logger.debug("Duplicate household at {} {}: {} / {}",
266	            request.getMethod(),
267	            request.getRequestURI(),
268	            e.getLastName(),
269	            e.getAddress());
270	        return ResponseEntity.status(status).body(detail);
271	    }
272	
273	    /**
274	     * Handles {@link CityAtCapacityException} raised when a create request supplies a
275	     * {@code city} that already contains the maximum number of owners (compared
276	     * case-insensitively). Returns a 409 Conflict whose body carries an {@code errors}
277	     * array naming the {@code city} field.
278	     *
279	     * @param e The {@link CityAtCapacityException} to be handled
280	     * @param request {@link HttpServletRequest} object referring to the current request.
281	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
282	     */
283	    @ExceptionHandler(CityAtCapacityException.class)
284	    @ResponseBody
285	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
286	        HttpStatus status = HttpStatus.CONFLICT;
287	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
288	        detail.setProperty("errors", List.of("city"));
289	        logger.debug("City at capacity at {} {}: {}",
290	            request.getMethod(),
291	            request.getRequestURI(),
292	            e.getCity());
293	        return ResponseEntity.status(status).body(detail);
294	    }
295	
296	    /**
297	     * Handles {@link DailyOwnerLimitExceededException} raised when a create request arrives
298	     * after the maximum number of owners for the current day (counted by
299	     * {@code registrationDate}) has already been reached. Returns a 429 Too Many Requests.
300	     *
301	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
302	     * @param request {@link HttpServletRequest} object referring to the current request.
303	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
304	     */
305	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
306	    @ResponseBody
307	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
308	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
309	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
310	        detail.setProperty("errors", List.of("registrationDate"));
311	        logger.debug("Daily owner limit reached at {} {}: {}",
312	            request.getMethod(),
313	            request.getRequestURI(),
314	            e.getDate());
315	        return ResponseEntity.status(status).body(detail);
316	    }
317	
318	}
